      "status": "review",
      "note": "A reviewer can reconstruct the complaint timeline and factual allegations, but cannot reconstruct the investigative findings or the Agency's evidentiary assessment that led to the discrimination determination, as the ROI content is summarized only through page citations (238, 61) without substantive investigation conclusions."
    },
    "accountability_support": {
      "status": "gap",
      "note": "The record provides complainant's allegations and the Agency's final conclusion, but does not document what investigative evidence was gathered regarding selection panel composition, scoring criteria, comparators, temporal proximity between the harassment report and non-selection, or other factors necessary to support a discrimination finding or rejection."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "The chronology is complete and clear: March 25, 2022 (harassment incident), May 2, 2022 (two non-selections learned), May 3, 2022 (complaint initiated), June 29, 2022 (EEO complaint filed), investigation concluded, and final decision issued after no hearing request received."
    }
